// ENG-1884 proof: which canvas shapes offer "Convert To", and where the node lands.
const PAGE_TITLE = `Canvas/ENG-1884 verify ${Date.now()}`;

const FIXTURES = [
  { key: "text-with-text", type: "text", text: "text shape", expect: true },
  { key: "text-empty", type: "text", text: "", expect: true },
  { key: "geo-with-text", type: "geo", text: "geo with text", expect: true },
  { key: "geo-empty", type: "geo", text: "", expect: false },
  { key: "geo-whitespace", type: "geo", text: "   ", expect: false },
  { key: "note-with-text", type: "note", text: "note with text", expect: true },
  { key: "note-empty", type: "note", text: "", expect: false },
  { key: "arrow-with-text", type: "arrow", text: "arrow label", expect: false },
  { key: "geo-locked", type: "geo", text: "locked", expect: false, locked: true },
];

const waitFor = async (page, fn, timeout = 30000, label = "condition") => {
  const start = Date.now();
  for (;;) {
    if (await page.evaluate(fn)) return;
    if (Date.now() - start > timeout) throw new Error(`timeout waiting for ${label}`);
    await page.waitForTimeout(250);
  }
};

export default {
  async ready({ page }) {
    await page.evaluate(async (title) => {
      await window.roamAlphaAPI.data.page.create({ page: { title } });
      const uid = window.roamAlphaAPI.q(
        `[:find ?u . :where [?p :node/title "${title}"] [?p :block/uid ?u]]`,
      );
      await window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } });
    }, PAGE_TITLE);

    await page.waitForSelector(".tl-canvas", { timeout: 60000 });
    await waitFor(page, `Boolean(window.tldrawApps && window.tldrawApps[${JSON.stringify(PAGE_TITLE)}])`,
      60000, "tldraw editor");
    return true;
  },

  async run({ page }) {
    // Lay the fixtures out in a row so each has its own hit area.
    const ids = await page.evaluate(
      ({ title, fixtures }) => {
        const editor = window.tldrawApps[title];
        editor.selectAll().deleteShapes(editor.getSelectedShapeIds());
        const made = {};
        fixtures.forEach((f, i) => {
          const id = `shape:eng1884_${f.key.replace(/-/g, "_")}`;
          const x = 100 + i * 260;
          const base = { id, type: f.type, x, y: 200 };
          if (f.type === "arrow") {
            editor.createShapes([{ ...base, props: { text: f.text, start: { x: 0, y: 0 }, end: { x: 160, y: 0 } } }]);
          } else if (f.type === "geo") {
            editor.createShapes([{ ...base, props: { geo: "rectangle", w: 200, h: 120, text: f.text } }]);
          } else if (f.type === "note") {
            editor.createShapes([{ ...base, props: { text: f.text } }]);
          } else {
            editor.createShapes([{ ...base, props: { text: f.text } }]);
          }
          if (f.locked) editor.updateShapes([{ id, type: f.type, isLocked: true }]);
          made[f.key] = id;
        });
        editor.zoomToFit();
        return made;
      },
      { title: PAGE_TITLE, fixtures: FIXTURES },
    );

    const gate = [];
    for (const f of FIXTURES) {
      const pt = await page.evaluate(
        ({ title, id }) => {
          const editor = window.tldrawApps[title];
          const b = editor.getShapePageBounds(id);
          const v = editor.pageToViewport({ x: b.midX, y: b.midY });
          const rect = document.querySelector(".tl-container").getBoundingClientRect();
          editor.select(id);
