mkdir -p "$W/local/roam-playwright/demo/frames"
cat > "$W/local/roam-playwright/eng-1884-demo.mjs" <<'MODULE'
// ENG-1884 demo: converting a shape inside a frame, and inside a two-shape group.
// Captures a paced PNG sequence; ffmpeg stitches it afterwards.
import fs from "node:fs";
import path from "node:path";

const FPS = 10;
const PAGE_TITLE = `Canvas/ENG-1884 demo ${Date.now()}`;
const OUT = path.resolve("local/roam-playwright/demo");
const FRAMES = path.join(OUT, "frames");
const NODE_TYPE_LABEL = "Claim";

let frame = 0;
const createdPages = [PAGE_TITLE];

const shoot = async (page) => {
  frame += 1;
  await page.screenshot({
    path: path.join(FRAMES, `f${String(frame).padStart(5, "0")}.png`),
  });
};
// Hold the current picture for ms of real-time playback.
const hold = async (page, ms) => {
  const n = Math.max(1, Math.round((ms / 1000) * FPS));
  for (let i = 0; i < n; i += 1) await shoot(page);
};

const caption = async (page, title, sub = "") => {
  await page.evaluate(
    ({ title, sub }) => {
      let el = document.getElementById("dg-demo-caption");
      if (!el) {
        el = document.createElement("div");
        el.id = "dg-demo-caption";
        el.style.cssText = [
          "position:fixed", "left:0", "right:0", "bottom:0", "z-index:2147483647",
          "background:rgba(17,17,17,.92)", "color:#fff", "padding:14px 22px",
          "font:600 19px/1.35 -apple-system,Segoe UI,sans-serif", "pointer-events:none",
appendChild: 0,
        ].filter((v) => typeof v === "string").join(";");
        document.body.appendChild(el);
      }
      el.innerHTML = `<div>${title}</div>` +
        (sub ? `<div style="font-weight:400;font-size:15px;opacity:.8;margin-top:4px">${sub}</div>` : "");
    },
    { title, sub },
  );
};

const ensureCursor = async (page) => {
  await page.evaluate(() => {
    if (document.getElementById("dg-demo-cursor")) return;
    const c = document.createElement("div");
    c.id = "dg-demo-cursor";
    c.style.cssText = [
      "position:fixed", "width:22px", "height:22px", "z-index:2147483647",
      "pointer-events:none", "margin:-2px 0 0 -2px",
      "background:no-repeat center/contain url(\"data:image/svg+xml;utf8," +
        encodeURIComponent(
          '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M5 2l14 10-6.5 1.2L15 21l-3 1-2.6-7.3L5 19z" fill="%23fff" stroke="%23000" stroke-width="1.5"/></svg>',
        ) + "\")",
    ].join(";");
    document.body.appendChild(c);
    window.__dgCursor = (x, y) => {
      c.style.left = `${x}px`;
      c.style.top = `${y}px`;
    };
  });
};

// Glide the drawn cursor to a point, capturing frames, then put the real mouse there.
const moveTo = async (page, x, y, ms = 500) => {
  const steps = Math.max(2, Math.round((ms / 1000) * FPS));
  const from = (await page.evaluate(() => {
    const c = document.getElementById("dg-demo-cursor");
    return c ? [parseFloat(c.style.left) || 0, parseFloat(c.style.top) || 0] : [0, 0];
  }));
  for (let i = 1; i <= steps; i += 1) {
    const t = i / steps;
    const ease = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    const cx = from[0] + (x - from[0]) * ease;
    const cy = from[1] + (y - from[1]) * ease;
    await page.evaluate(([px, py]) => window.__dgCursor(px, py), [cx, cy]);
    await page.mouse.move(cx, cy);
    await shoot(page);
  }
  await page.mouse.move(x, y);
};

const closeDialogs = async (page) => {
  for (let i = 0; i < 4; i += 1) {
    if (!(await page.evaluate(() => Boolean(document.querySelector(".bp3-dialog, .bp3-overlay-open"))))) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(400);
  }
};

const waitFor = async (page, fn, t = 60000, l = "condition") => {
  const s = Date.now();
  for (;;) {
    if (await page.evaluate(fn)) return;
    if (Date.now() - s > t) throw new Error(`timeout waiting for ${l}`);
    await page.waitForTimeout(250);
  }
};

const screenPointOf = (page, id) =>
  page.evaluate(
    ({ title, id }) => {
      const editor = window.tldrawApps[title];
      const b = editor.getShapePageBounds(id);
      const v = editor.pageToViewport({ x: b.midX, y: b.midY });
      const r = document.querySelector(".tl-container").getBoundingClientRect();
      return { x: r.left + v.x, y: r.top + v.y };
    },
    { title: PAGE_TITLE, id },
  );

const clickMenuItem = async (page, label) => {
  const el = page.locator(`.tlui-menu >> text="${label}"`).first();
  const box = await el.boundingBox();
  if (!box) throw new Error(`menu item not found: ${label}`);
  await moveTo(page, box.x + box.width / 2, box.y + box.height / 2, 420);
  await hold(page, 350);
  await el.click();
  await page.waitForTimeout(350);
};

export default {
  async ready({ page }) {
    fs.rmSync(FRAMES, { recursive: true, force: true });
    fs.mkdirSync(FRAMES, { recursive: true });
    await closeDialogs(page);
    await page.evaluate(async (title) => {
      await window.roamAlphaAPI.data.page.create({ page: { title } });
      const uid = window.roamAlphaAPI.q(`[:find ?u . :where [?p :node/title "${title}"] [?p :block/uid ?u]]`);
      await window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } });
    }, PAGE_TITLE);
    await page.waitForSelector(".tl-canvas", { timeout: 60000 });
    await waitFor(page, `Boolean(window.tldrawApps && window.tldrawApps[${JSON.stringify(PAGE_TITLE)}])`, 60000, "editor");
    await closeDialogs(page);
    await ensureCursor(page);
    return true;
  },

  async run({ page }) {
    const results = {};

    // ---------- Scene 1: shape inside a frame ----------
    await caption(page, "ENG-1884 — Convert To on a shape inside a frame",
      "A frame's children store parent-relative x/y.");
    await page.evaluate((title) => {
      const editor = window.tldrawApps[title];
      editor.selectAll().deleteShapes(editor.getSelectedShapeIds());
      editor.createShapes([
        { id: "shape:demo_frame", type: "frame", x: 300, y: 200, props: { w: 520, h: 360, name: "My frame" } },
      ]);
      editor.createShapes([
        { id: "shape:demo_geo", type: "geo", parentId: "shape:demo_frame", x: 80, y: 90,
          props: { geo: "rectangle", w: 300, h: 150, text: "Caffeine improves recall" } },
      ]);
      editor.setCamera({ x: -300, y: -150, z: 1 });
      editor.selectNone();
    }, PAGE_TITLE);
    await hold(page, 2200);

    const before = await page.evaluate((title) => {
      const e = window.tldrawApps[title];
      const s = e.getShape("shape:demo_geo");
      const p = e.getShapePageTransform("shape:demo_geo").point();
      return { parentId: s.parentId, localX: s.x, localY: s.y, pageX: p.x, pageY: p.y };
    }, PAGE_TITLE);

    await caption(page, "The rectangle is a child of the frame",
      `local x/y = ${before.localX},${before.localY} · page x/y = ${before.pageX},${before.pageY}`);
    await hold(page, 2600);

    const geoPt = await screenPointOf(page, "shape:demo_geo");
    await caption(page, "Right-click the rectangle");
    await moveTo(page, geoPt.x, geoPt.y, 700);
    await hold(page, 500);
    await page.mouse.click(geoPt.x, geoPt.y, { button: "right" });
    await page.waitForTimeout(500);
    await hold(page, 1200);

    await caption(page, "Convert To is offered — this is what ENG-1884 adds",
      "Before this change the submenu appeared only for text and image shapes.");
    await hold(page, 2000);
    await clickMenuItem(page, "Convert To");
    await hold(page, 1000);
    await caption(page, `Pick a node type: ${NODE_TYPE_LABEL}`);
    await clickMenuItem(page, NODE_TYPE_LABEL);
    await hold(page, 900);

    await caption(page, "The dialog opens prefilled with the shape's own text",
      "Trim only decides emptiness; the text itself is passed through unchanged.");
    await page.waitForSelector(".roamjs-canvas-dialog", { timeout: 20000 });
    await hold(page, 2600);

    const confirm = page.locator(".roamjs-canvas-dialog button:has-text('Confirm')").first();
    const cb = await confirm.boundingBox();
    await moveTo(page, cb.x + cb.width / 2, cb.y + cb.height / 2, 600);
    await hold(page, 400);
    await confirm.click();
    await page.waitForTimeout(2500);
    await hold(page, 1200);

    const after = await page.evaluate((title) => {
      const e = window.tldrawApps[title];
      const node = e.getCurrentPageShapes().find((s) => s.type === "discourse-node");
      if (!node) return null;
      const p = e.getShapePageTransform(node.id).point();
      return { parentId: node.parentId, localX: node.x, localY: node.y, pageX: p.x, pageY: p.y,
               title: node.props.title, frameAlive: Boolean(e.getShape("shape:demo_frame")) };
    }, PAGE_TITLE);
    results.frameCase = { before, after,
      keptParent: after && after.parentId === before.parentId,
      keptPagePosition: after && after.pageX === before.pageX && after.pageY === before.pageY };

    await caption(page,
      results.frameCase.keptParent ? "The node stayed inside the frame, at the same spot"
                                   : "FAIL — the node left the frame",
      `parent ${after && after.parentId === before.parentId ? "unchanged" : "CHANGED"} · page x/y = ${after && after.pageX},${after && after.pageY}`);
    await hold(page, 3200);

    // ---------- Scene 2: two-shape group ----------
    await caption(page, "Second case — a group of exactly two shapes",
      "Deleting one child makes tldraw dissolve the group, so the parent disappears mid-conversion.");
    await page.evaluate((title) => {
      const editor = window.tldrawApps[title];
      editor.selectAll().deleteShapes(editor.getSelectedShapeIds());
      editor.createShapes([
        { id: "shape:demo_a", type: "geo", x: 320, y: 240, props: { geo: "rectangle", w: 260, h: 140, text: "Sleep aids consolidation" } },
        { id: "shape:demo_b", type: "geo", x: 650, y: 240, props: { geo: "ellipse", w: 200, h: 140, text: "partner" } },
      ]);
      editor.select("shape:demo_a", "shape:demo_b");
      editor.groupShapes(editor.getSelectedShapeIds());
      editor.setCamera({ x: -250, y: -160, z: 1 });
      editor.selectNone();
    }, PAGE_TITLE);
    await hold(page, 2400);

    const beforeG = await page.evaluate((title) => {
      const e = window.tldrawApps[title];
      const s = e.getShape("shape:demo_a");
      const p = e.getShapePageTransform("shape:demo_a").point();
      return { parentId: s.parentId, localX: s.x, localY: s.y, pageX: p.x, pageY: p.y };
    }, PAGE_TITLE);
    await caption(page, "Grouped: the rectangle's x/y are now group-relative",
      `local x/y = ${beforeG.localX},${beforeG.localY} · page x/y = ${beforeG.pageX},${beforeG.pageY}`);
    await hold(page, 2800);

    const aPt = await screenPointOf(page, "shape:demo_a");
    await caption(page, "Convert the rectangle inside the group");
    await moveTo(page, aPt.x, aPt.y, 700);
